class TokenBucket:
    def __init__(self, capacity, refill_per_sec):
        self.cap = capacity
        self.rate = refill_per_sec
        self.tokens = capacity
        self.last = 0.0

    def allow(self, now):
        # refill lazily from elapsed time, never above capacity
        self.tokens = min(self.cap, self.tokens + (now - self.last) * self.rate)
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True, 0.0
        # Retry-After: time until one whole token exists
        return False, round((1 - self.tokens) / self.rate, 2)

# O(1) time and memory per key. In production this state lives in Redis,
# updated inside one Lua script so read-decide-write is atomic.
buckets = {}
def check(key, now):
    b = buckets.setdefault(key, TokenBucket(capacity=3, refill_per_sec=1))
    return b.allow(now)

# a burst of 5 calls at t=0, then one call 2 seconds later
for t in [0, 0, 0, 0, 0, 2.0]:
    ok, retry = check("user:7", t)
    print("t=%.1f" % t, "200 OK" if ok else "429 Retry-After=%s" % retry)
print("other user is independent:", check("user:8", 0)[0])
